169: PyDoc_STRVAR(get_default_main_loop__doc__,
170: "get_default_main_loop() -> object\n\n"
171: "Return the global default dbus-python main loop wrapper, which is used\n"
172: "when no main loop wrapper is passed to the Connection constructor.\n"
173: "\n"
174: "If None, there is no default and you should always pass the mainloop\n"
175: "parameter to the constructor - if you don't, then asynchronous calls,\n"
176: "connecting to signals and exporting objects will raise an exception.\n"
177: "There is no default until set_default_main_loop is called.\n");
178: static PyObject *
