185: PyDoc_STRVAR(set_default_main_loop__doc__,
186: "set_default_main_loop(object)\n\n"
187: "Change the global default dbus-python main loop wrapper, which is used\n"
188: "when no main loop wrapper is passed to the Connection constructor.\n"
189: "\n"
190: "If None, return to the initial situation: there is no default, and you\n"
191: "must always pass the mainloop parameter to the constructor.\n"
192: "\n"
193: "Two types of main loop wrapper are planned in dbus-python.\n"
194: "Native main-loop wrappers are instances of `dbus.mainloop.NativeMainLoop`\n"
195: "supplied by extension modules like `dbus.mainloop.glib`: they have no\n"
196: "Python API, but connect themselves to ``libdbus`` using native code.\n"
197: 
198: "Python main-loop wrappers are not yet implemented. They will be objects\n"
199: "supporting the interface defined by `dbus.mainloop.MainLoop`, with an\n"
200: "API entirely based on Python methods.\n"
201: "\n"
202: );
203: static PyObject *
204: set_default_main_loop(PyObject *always_null UNUSED,
205:                       PyObject *args)
206: {
207:     PyObject *new_loop, *old_loop;
208: 
209:     if (!PyArg_ParseTuple(args, "O", &new_loop)) {
210:         return NULL;
211:     }
212:     if (!dbus_py_check_mainloop_sanity(new_loop)) {
213:         return NULL;
214:     }
215:     old_loop = default_main_loop;
216:     Py_INCREF(new_loop);
217:     default_main_loop = new_loop;
218:     Py_CLEAR(old_loop);
219:     Py_RETURN_NONE;
220: }
