88: static dbus_bool_t
89: DBusPyServer_set_auth_mechanisms(Server *self,
90:                                  PyObject *auth_mechanisms)
91: {
92:     PyObject *fast_seq = NULL, *references = NULL;
93:     Py_ssize_t length;
94:     Py_ssize_t i;
95:     /* a mutable array of constant strings */
96:     const char **list = NULL;
97:     dbus_bool_t ret = FALSE;
98: 
99:     fast_seq = PySequence_Fast(auth_mechanisms,
100:             "Expecting sequence for auth_mechanisms parameter");
101: 
102:     if (!fast_seq)
103:         return FALSE;
104: 
105:     length = PySequence_Fast_GET_SIZE(fast_seq);
106: 
107:     list = calloc (length + 1, sizeof (char *));
108: 
109:     if (!list) {
110:         PyErr_NoMemory();
111:         goto finally;
112:     }
113: 
114:     if (!(references = PyTuple_New(length)))
115:         goto finally;
116: 
117:     for (i = 0; i < length; ++i) {
118:         PyObject *am, *am_as_bytes;
119: 
120:         am = PySequence_Fast_GET_ITEM(auth_mechanisms, i);
121:         if (!am)
122:             goto finally;
123: 
124:         if (PyUnicode_Check(am)) {
125:             am_as_bytes = PyUnicode_AsUTF8String(am);
126:             if (!am_as_bytes)
127:                 goto finally;
128:         }
129:         else {
130:             am_as_bytes = am;
131:             Py_INCREF(am_as_bytes);
132:         }
133:         list[i] = PyBytes_AsString(am_as_bytes);
134:         if (!list[i])
135:             goto finally;
136: 
137:         PyTuple_SET_ITEM(references, i, am_as_bytes);
138:     }
139: 
140:     list[length] = NULL;
141: 
142:     Py_BEGIN_ALLOW_THREADS
143:     dbus_server_set_auth_mechanisms(self->server, list);
144:     Py_END_ALLOW_THREADS
145: 
146:     ret = TRUE;
147: 
148: finally:
149:     if (list)
150:         free (list);
151:     Py_CLEAR(fast_seq);
152:     Py_CLEAR(references);
153:     return ret;
154: }
