216:                 wrapper, ((Server*) self)->mainloop, NULL);
217:         Py_CLEAR(wrapper);
218: 
219:         if (!conn_obj)
220:             goto out;
221: 
222:         result = PyObject_CallFunctionObjArgs(method, conn_obj, NULL);
223:         Py_CLEAR (conn_obj);
224: 
225:         /* discard result if not NULL, and fall through regardless */
226:         Py_CLEAR(result);
227:     }
