239: /* Return a new reference to a Python Server or subclass (given by cls)
240:  * corresponding to the DBusServer server, which must have been newly
241:  * created. For use by the Server constructor.
242:  *
243:  * Raises AssertionError if the DBusServer already has a Server.
244:  *
245:  * One reference to server is stolen - either the returned DBusPyServer
246:  * claims it, or it's unreffed.
247:  */
248: static PyObject *
249: DBusPyServer_NewConsumingDBusServer(PyTypeObject *cls,
250:                                     DBusServer *server,
251:                                     PyObject *conn_class,
252:                                     PyObject *mainloop,
253:                                     PyObject *auth_mechanisms)
254: {
255:     Server *self = NULL;
256:     PyObject *ref;
257:     dbus_bool_t ok;
258: 
259:     DBG("%s(cls=%p, server=%p, mainloop=%p, auth_mechanisms=%p)",
260:         __func__, cls, server, mainloop, auth_mechanisms);
261:     DBUS_PY_RAISE_VIA_NULL_IF_FAIL(server);
262: 
263:     Py_BEGIN_ALLOW_THREADS
264:     ref = (PyObject *)dbus_server_get_data(server,
265:                                            _server_python_slot);
266:     Py_END_ALLOW_THREADS
267:     if (ref) {
268:         PyObject *obj = NULL;
269:         if (PyWeakref_GetRef(ref, &obj) < 0) {
270:             return NULL;
271:         }
272:         ref = NULL;
273:         if (obj && obj != Py_None) {
274:             PyErr_SetString(PyExc_AssertionError,
275:                             "Newly created D-Bus server already has a "
276:                             "Server instance associated with it");
277:             DBG("%s() fail - assertion failed, DBusPyServer has a DBusServer already", __func__);
278:             DBG_WHEREAMI;
279:             Py_CLEAR(obj);
280:             return NULL;
281:         }
282:         Py_CLEAR(obj);
283:     }
284:     ref = NULL;
285: 
286:     /* Change mainloop from a borrowed reference to an owned reference */
287:     if (!mainloop || mainloop == Py_None) {
288:         mainloop = dbus_py_get_default_main_loop();
289: 
290:         if (!mainloop || mainloop == Py_None) {
291:             PyErr_SetString(PyExc_RuntimeError,
292:                             "To run a D-Bus server, you need to either "
293:                             "pass mainloop=... to the constructor or call "
294:                             "dbus.set_default_main_loop(...)");
295:             goto err;
296:         }
297:     }
298:     else {
299:         Py_INCREF(mainloop);
300:     }
301: 
302:     DBG("Constructing Server from DBusServer at %p", server);
303: 
304:     self = (Server *)(cls->tp_alloc(cls, 0));
305:     if (!self) goto err;
306:     TRACE(self);
307: 
308:     DBG_WHEREAMI;
309: 
310:     self->server = NULL;
311: 
312:     Py_INCREF(conn_class);
313:     self->conn_class = conn_class;
314: 
315:     self->mainloop = mainloop;
316:     mainloop = NULL;    /* don't DECREF it - the DBusServer owns it now */
317: 
318:     ref = PyWeakref_NewRef((PyObject *)self, NULL);
319:     if (!ref) goto err;
320:     DBG("Created weak ref %p to (Server *)%p for (DBusServer *)%p",
321:         ref, self, server);
322: 
323:     Py_BEGIN_ALLOW_THREADS
324:     ok = dbus_server_set_data(server, _server_python_slot,
325:                               (void *)ref,
326:                               (DBusFreeFunction)dbus_py_take_gil_and_xdecref);
327:     Py_END_ALLOW_THREADS
328: 
329:     if (ok) {
330:         DBG("Attached weak ref %p ((Server *)%p) to (DBusServer *)%p",
331:             ref, self, server);
332: 
333:         ref = NULL;     /* don't DECREF it - the DBusServer owns it now */
334:     }
335:     else {
336:         DBG("Failed to attached weak ref %p ((Server *)%p) to "
337:             "(DBusServer *)%p - will dispose of it", ref, self, server);
338:         PyErr_NoMemory();
339:         goto err;
340:     }
341: 
342:     DBUS_PY_RAISE_VIA_GOTO_IF_FAIL(server, err);
343:     self->server = server;
344:     /* the DBusPyServer will close it now */
345:     server = NULL;
346: 
347:     if (self->mainloop != Py_None &&
348:         !dbus_py_set_up_server((PyObject *)self, self->mainloop))
349:         goto err;
350: 
351:     if (auth_mechanisms && auth_mechanisms != Py_None &&
352:         !DBusPyServer_set_auth_mechanisms(self, auth_mechanisms))
353:         goto err;
354: 
355:     Py_BEGIN_ALLOW_THREADS
356:     dbus_server_set_new_connection_function(self->server,
357:                                             DBusPyServer_new_connection_cb,
358:                                             NULL, NULL);
359:     Py_END_ALLOW_THREADS
360: 
361:     DBG("%s() -> %p", __func__, self);
362:     TRACE(self);
363:     return (PyObject *)self;
364: 
365: err:
366:     DBG("Failed to construct Server from DBusServer at %p", server);
367:     Py_CLEAR(mainloop);
368:     Py_CLEAR(self);
369:     Py_CLEAR(ref);
370: 
371:     if (server) {
372:         Py_BEGIN_ALLOW_THREADS
373:         dbus_server_disconnect(server);
374:         dbus_server_unref(server);
375:         Py_END_ALLOW_THREADS
376:     }
377: 
378:     DBG("%s() fail", __func__);
379:     DBG_WHEREAMI;
380:     return NULL;
381: }
