437: static void Server_tp_dealloc(Server *self)
438: {
439:     DBusServer *server = self->server;
440:     PyObject *et, *ev, *etb;
441: 
442:     /* avoid clobbering any pending exception */
443:     PyErr_Fetch(&et, &ev, &etb);
444: 
445: #if !DBUSPY_PY_VERSION_AT_LEAST(3, 12, 0, 0)
446:     if (self->weaklist)
447: #endif
448:     {
449:         PyObject_ClearWeakRefs((PyObject *)self);
450:     }
451: 
452:     TRACE(self);
453:     DBG("Deallocating Server at %p (DBusServer at %p)", self, server);
454:     DBG_WHEREAMI;
455: 
456:     if (server) {
457:         DBG("Server at %p has a server, disconnecting it...", self);
458:         Py_BEGIN_ALLOW_THREADS
459:         dbus_server_disconnect(server);
460:         Py_END_ALLOW_THREADS
461:     }
462: 
463:     Py_CLEAR(self->mainloop);
464: 
465:     /* make sure to do this last to preserve the invariant that
466:      * self->server is always non-NULL for any referenced Server.
467:      */
468:     DBG("Server at %p: nulling self->server", self);
469:     self->server = NULL;
470: 
471:     if (server) {
472:         DBG("Server at %p: unreffing server", self);
473:         dbus_server_unref(server);
474:     }
475: 
476:     DBG("Server at %p: freeing self", self);
477:     PyErr_Restore(et, ev, etb);
478:     (Py_TYPE(self)->tp_free)((PyObject *)self);
